**ApiTools.cs** — Tool class wrapping a REST API:

```csharp
using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Text.Json;

[McpServerToolType]
public class ApiTools(HttpClient httpClient, ILogger<ApiTools> logger)
{
    [McpServerTool, Description("Fetch a user by their unique ID.")]
    public async Task<string> GetUser(
        [Description("The numeric user ID")] int userId,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Fetching user {UserId}", userId);
        var json = await httpClient.GetStringAsync(
            $"/users/{userId}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("Search users by name. Returns matching results.")]
    public async Task<string> SearchUsers(
        [Description("Name or partial name to search for")] string query,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Searching users: {Query}", query);
        var json = await httpClient.GetStringAsync(
            $"/users?name={Uri.EscapeDataString(query)}", cancellationToken);
        return json;
    }

    [McpServerTool, Description("Create a new user with the given name and email.")]
    public async Task<string> CreateUser(
        [Description("Full name of the user")] string name,
        [Description("Email address")] string email,
        CancellationToken cancellationToken = default)
    {
        logger.LogInformation("Creating user {Name}", name);
        var payload = JsonSerializer.Serialize(new { name, email });
        var response = await httpClient.PostAsync(
            "/users",
            new StringContent(payload, System.Text.Encoding.UTF8, "application/json"),
            cancellationToken);

        response.EnsureSuccessStatusCode();
        return await response.Content.ReadAsStringAsync(cancellationToken);
    }
}
```

**Program.cs** — stdio transport with DI:

```csharp
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging;
using ModelContextProtocol.Server;

var builder = Host.CreateApplicationBuilder(args);

// CRITICAL: route all logging to stderr so stdout stays clean for JSON-RPC
builder.Logging.AddConsole(options =>
    options.LogToStandardErrorThreshold = LogLevel.Trace);

// Register HttpClient with a base address for the API
builder.Services.AddHttpClient<ApiTools>(client =>
{
    client.BaseAddress = new Uri("https://jsonplaceholder.typicode.com");
});

builder.Services.AddMcpServer(options =>
{
    options.ServerInfo = new() { Name = "ApiServer", Version = "1.0.0" };
})
.WithStdioServerTransport()
.WithToolsFromAssembly();

await builder.Build().RunAsync();
```

---

### How DI works for MCP tools

The SDK supports **two injection styles**:

| Style | How it works |
|-------|-------------|
| **Constructor injection** (non-static class) | The class gets a DI-resolved instance per invocation. Services like `HttpClient`, `ILogger<T>`, or your own types go in the **primary constructor**. This is the recommended pattern when tools share dependencies. |
| **Method parameter injection** (static class) | DI services can appear directly as **method parameters**. The SDK inspects each parameter's type — if it's registered in DI, it injects it instead of exposing it in the tool schema. |

**Key rule:** `CancellationToken`, `IMcpServer`, `IProgress<ProgressNotificationValue>`, and any DI-registered service are **automatically injected** and never appear in the JSON schema sent to the LLM. Only parameters with `[Description]` are user-facing.

In the example above, `HttpClient` and `ILogger<ApiTools>` are injected via constructor. The `AddHttpClient<ApiTools>()` call registers a typed `HttpClient` specifically for the `ApiTools` class, giving it a dedicated base address and handler pipeline.
